{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "action": { "type": "string", "enum": ["repondre", "agir", "attendre", "lire", "rien"], "description": "Ce que l'email attend de Gauthier." },
    "domaine": { "type": "string", "enum": ["emploi_formation", "admin_finance", "pro", "recherche_reseau", "perso", "achats", "promo"], "description": "Thème de l'email." },
    "echeance": { "type": ["string", "null"], "description": "Date limite au format AAAA-MM-JJ, ou null." },
    "raison": { "type": "string", "description": "Une phrase qui justifie action et domaine." }
  },
  "required": ["action", "domaine", "echeance", "raison"],
  "additionalProperties": false
}

parameters.jsCode:
const o = $json.output || {};
const mail = $('Loop Over Items').item.json;
const today = DateTime.now().setZone('Europe/Paris').startOf('day');
let days_left = null;
if (o.echeance) {
  const d = DateTime.fromISO(o.echeance, { zone: 'Europe/Paris' });
  if (d.isValid) days_left = Math.round(d.startOf('day').diff(today, 'days').days);
}
const IMPORTANT = ['emploi_formation', 'admin_finance', 'pro', 'recherche_reseau', 'perso'];
let category = null;
if (o.action) {
  if (o.domaine === 'promo') category = 'ignorer';
  else if (['repondre', 'agir'].includes(o.action)) category = (days_left !== null && days_left <= 2) ? 'urgent' : 'a_traiter';
  else if (o.action === 'attendre') category = 'en_attente';
  else if (o.action === 'lire') category = IMPORTANT.includes(o.domaine) ? 'a_lire' : 'ignorer';
  else category = 'ignorer';
}
return { json: {
  mail_id: mail.mail_id, titre: mail.mail_title, expediteur: mail.sender_email, source_type: mail.source_type,
  ancienne_categorie: mail.category, ancienne_origine: mail.category_origin,
  action: o.action ?? null, domaine: o.domaine ?? null, echeance: o.echeance ?? null, days_left,
  nouvelle_categorie: category, raison: o.raison ?? null, error: $json.error ?? null
} };
